uniform float speed : 0.0 .. 5.0 = 2.0;
uniform float density : 0.0 .. 1.0 = 0.3;
uniform float lifetime : 0.0 .. 10.0 = 8.0;
uniform float width : 0.0 .. 1.0 = 0.5;
uniform vec3 tint : color = 0.0, 1.0, 0.0;
uniform bool trail : toggle = true;

state fixed ph;
state fixed drift;
state fixed densityState;
state fixed lifetimeState;
state fixed widthState;
buffer fixed8 rain[500]; // each LED holds rain intensity 0..1

void update() {
  ph = fract(ph + fixed(dt * speed * 0.2)); // phase for sine wave
  drift = drift + fixed(dt * speed * 0.05); // steady drift offset
  densityState = fixed(density);
  lifetimeState = fixed(lifetime);
  widthState = fixed(width);
  // initialize rain buffer on first frame
  if (frame == 0) {
    for (int i = 0; i < 500; i = i + 1) {
      rain[i] = fixed8(densityState);
    }
  }
}

vec3 shade(Led led) {
  fixed idx = fixed(led.idx);
  fixed s = fixed(led.s);
  fixed y = fixed(led.pos.y);
  fixed uvx = fixed(led.uv.x);
  fixed uvz = fixed(led.uv.y);

  // rain intensity per LED from buffer
  fixed rainVal = fixed(rain[led.idx]);
  // decay rain over time
  rainVal = rainVal * fixed(0.995);
  // new rain spawns at top with density
  if (rainVal < densityState) {
    rainVal = rainVal + fixed(0.05);
  }
  // store back
  rain[led.idx] = fixed8(rainVal);

  // horizontal wave motion
  fixed wave = sin(fixed(2.0) * (s + ph + drift * uvx) + ph) * fixed(0.5) + fixed(0.5);
  // vertical fall factor based on y and lifetime
  fixed fall = exp((fixed(1.0) - y) * fixed(1.0 / lifetimeState));
  // combine into brightness
  fixed bright = rainVal * wave * fall;
  // width ramp
  bright = clamp((bright - (fixed(1.0) - widthState)) * fixed(20.0), fixed(0.0), fixed(1.0));

  // color: hsv based on brightness and phase
  fixed hue = fract(ph + wave * fixed(0.3));
  vec3 col = hsv2rgb(hue, fixed(0.9), bright);
  // apply tint
  col = col * tint;

  // optional trail effect: blend with previous buffer value
  if (trail) {
    fixed8 prev = rain[led.idx];
    fixed8 blend = fixed8(col.r * 0.7 + prev.r * 0.3);
    col.r = blend;
    col.g = blend;
    col.b = blend;
  }

  return col;
}

